const RENDER_REL = "out/renderer/assets/styles-DyAcaLKy.js";
const PRELOAD_ANCHOR = "exposeInMainWorld(\"zcode\",{connectRemote";
const PRELOAD_INJECT = "modelhubFetchModels:(e,t)=>h.ipcRenderer.invoke(\"modelhub:fetch-models\",{baseUrl:e,apiKey:t}),modelhubProbeVision:(e,t,n)=>h.ipcRenderer.invoke(\"modelhub:probe-vision\",{baseUrl:e,apiKey:t,model:n}),";
const ORIG_ADD_BTN = "(0,$.jsx)(X,{type:`button`,size:`lg`,disabled:y,onClick:()=>{v()},children:r.formatMessage({id:`settings.modelProvider.addProviderAction`})})";
const ORIG_QPT = "(0,$.jsx)(QPt,{models:M,apiKeyValue:O,currentApiFormat:w,apiFormatOptions:VPt(e),onTestModel:r?se:void 0,onModelCommit:G,onDeleteModel:ue,onAddModel:de,readOnly:g,editMode:_})";
